#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Role definitions for gRPC service RBAC */
#define ROLE_GUEST      0x00
#define ROLE_USER       0x01
#define ROLE_MODERATOR  0x02
#define ROLE_ADMIN      0x04
#define ROLE_SUPERADMIN  0x08

/* Permission flags */
#define PERM_READ       0x01
#define PERM_WRITE      0x02
#define PERM_DELETE     0x04
#define PERM_MANAGE     0x08
#define PERM_ESCALATE   0x10

typedef struct {
    char username[64];
    uint8_t role;
    uint8_t permissions;
    uint8_t session_flags;
    uint8_t _padding;
} grpc_auth_context_t;

typedef struct {
    char method[128];
    char token[256];
    uint8_t requested_role;
    uint8_t metadata_count;
    char metadata_keys[8][32];
    char metadata_values[8][64];
} grpc_request_t;

/* Simulated token store - in production this would be a DB lookup */
static grpc_auth_context_t active_sessions[64];
static int session_count = 0;

/* Compute effective permissions from role hierarchy */
static uint8_t compute_permissions(uint8_t role) {
    uint8_t perms = PERM_READ; /* everyone can read */
    if (role >= ROLE_USER) perms |= PERM_WRITE;
    if (role >= ROLE_MODERATOR) perms |= PERM_DELETE;
    if (role >= ROLE_ADMIN) perms |= PERM_MANAGE;
    if (role >= ROLE_SUPERADMIN) perms |= PERM_ESCALATE;
    return perms;
}

/* Validate that a role transition is permitted.
 * Users can only request roles <= their current role.
 * The RBAC policy: role escalation requires PERM_ESCALATE. */
static int validate_role_transition(const grpc_auth_context_t *ctx, uint8_t target_role) {
    /* If requesting same or lower role, always allowed */
    if (target_role <= ctx->role) return 1;

    /* Escalation requires explicit permission */
    if (ctx->permissions & PERM_ESCALATE) return 1;

    return 0;
}

/* Parse delegation metadata from gRPC request headers.
 * Supports "x-delegated-role" for service-to-service calls. */
static int parse_delegation_metadata(const grpc_request_t *req, uint8_t *delegated_role) {
    for (int i = 0; i < req->metadata_count && i < 8; i++) {
        /* Bounded compare: metadata_keys are fixed-size buffers that may not be
         * NUL-terminated when populated from untrusted input. */
        if (strncmp(req->metadata_keys[i], "x-delegated-role", sizeof(req->metadata_keys[i])) == 0) {
            /* Copy value into a guaranteed NUL-terminated bounded buffer before atoi. */
            char value_buf[sizeof(req->metadata_values[i]) + 1];
            memcpy(value_buf, req->metadata_values[i], sizeof(req->metadata_values[i]));
            value_buf[sizeof(req->metadata_values[i])] = '\0';
            int role_val = atoi(value_buf);
            if (role_val >= 0 && role_val <= 0x08) {
                *delegated_role = (uint8_t)role_val;
                return 1;
            }
        }
    }
    return 0;
}

/* Authenticate and authorize a gRPC request.
 * Returns the effective auth context for the request. */
grpc_auth_context_t* grpc_authorize_request(grpc_request_t *req) {
    grpc_auth_context_t *ctx = NULL;

    /* Find session by token */
    for (int i = 0; i < session_count; i++) {
        if (strncmp(active_sessions[i].username, req->token, 63) == 0) {
            ctx = &active_sessions[i];
            break;
        }
    }

    if (!ctx) return NULL;

    /* Check for delegation metadata (service mesh internal calls) */
    uint8_t delegated_role = 0;
    int has_delegation = parse_delegation_metadata(req, &delegated_role);

    /* Determine effective role for this request */
    uint8_t effective_role = ctx->role;

    if (has_delegation) {
        /* Delegation: the calling service asserts a role.
         * We trust delegation only if the caller has MANAGE permission
         * AND the delegated role doesn't exceed the caller's own role. */
        if ((ctx->permissions & PERM_MANAGE) && (delegated_role <= ctx->role)) {
            effective_role = delegated_role;
        }
    }

    /* Handle explicit role escalation request */
    if (req->requested_role != 0 && req->requested_role != effective_role) {
        /* Validate against ORIGINAL context - not the delegated one */
        if (validate_role_transition(ctx, req->requested_role)) {
            effective_role = req->requested_role;
        }
    }

    /* Return a copy with effective permissions - don't mutate session */
    static grpc_auth_context_t result_ctx;
    memcpy(&result_ctx, ctx, sizeof(grpc_auth_context_t));
    result_ctx.role = effective_role;
    result_ctx.permissions = compute_permissions(effective_role);

    return &result_ctx;
}

/* Register a new session (called after initial authentication) */
int grpc_register_session(const char *username, uint8_t initial_role) {
    if (session_count >= 64) return -1;
    grpc_auth_context_t *ctx = &active_sessions[session_count];
    memset(ctx, 0, sizeof(grpc_auth_context_t));
    strncpy(ctx->username, username, 63);
    ctx->username[63] = '\0';
    ctx->role = initial_role;
    ctx->permissions = compute_permissions(initial_role);
    session_count++;
    return 0;
}

/* Example: admin endpoint handler */
int handle_admin_endpoint(grpc_request_t *req) {
    grpc_auth_context_t *ctx = grpc_authorize_request(req);
    if (!ctx) return -1; /* unauthenticated */

    if (!(ctx->permissions & PERM_MANAGE)) {
        return -2; /* forbidden */
    }

    printf("Admin action performed by: %s (role=0x%02x)\n", ctx->username, ctx->role);
    return 0;
}

int main() {
    /* Setup: register a normal user */
    grpc_register_session("alice", ROLE_USER);
    grpc_register_session("bob", ROLE_ADMIN);

    /* Normal user tries admin endpoint */
    grpc_request_t req;
    memset(&req, 0, sizeof(req));
    strncpy(req.token, "alice", 255);
    req.token[255] = '\0';
    strncpy(req.method, "/admin.Service/ManageUsers", 127);
    req.method[127] = '\0';
    req.requested_role = ROLE_ADMIN;

    int result = handle_admin_endpoint(&req);
    printf("Alice admin attempt: %d\n", result);

    return 0;
}
